shellCommands.command:
cat << 'EOF' > app/actions.ts
'use server';

import { updateTag } from 'next/cache';

export async function createPost(formData: FormData) {
  const title = formData.get('title');
  const content = formData.get('content');

  // In a real application, you would save this to a database here.
  // Example: await db.post.create({ data: { title, content } });

  if (!title || !content) {
    throw new Error('Title and content are required');
  }

  // Use updateTag to guarantee read-your-own-writes and ensure no stale 
  // content is served on the next page load. Unlike revalidateTag (which 
  // serves stale-while-revalidate), updateTag immediately expires the cache.
  updateTag('posts');
}
EOF

cat << 'EOF' > app/page.tsx
import { createPost } from './actions';

export default function Home() {
  return (
    <main>
      <h1>Posts</h1>
      <p>Please implement a Server Action for creating posts with cache invalidation.</p>

      <form action={createPost}>
        <input name="title" placeholder="Title" required />
        <textarea name="content" placeholder="Content" required />
        <button type="submit">Create Post</button>
      </form>
    </main>
  );
}
EOF
